/* GENERATED by scripts/build-sw.mjs — the precache list and version are filled
   in from the built output, so a hashed filename can never go stale.

   Cache-first for everything static: after the first load the network is only
   ever used for peer-to-peer signalling, and the app is fully playable with it
   switched off. A new version never reloads by itself — the page is told, and
   the person decides when. Reloading mid-game would throw the board away. */

const CACHE = 'kissa-__VERSION__';
const ASSETS = __ASSETS__;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(ASSETS);
    // No skipWaiting: the running page keeps the version it started with until
    // the person asks for the new one.
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key !== CACHE && key.startsWith('kissa-')) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'skip-waiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const request = event.request;
  if (request.method !== 'GET') return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;

  event.respondWith((async () => {
    // ignoreVary matters more than it looks. Static hosts commonly answer with
    // `Vary: Origin`, and the Cache API honours it: addAll() stores these
    // against a request with no Origin header, while a module script sends one,
    // so every asset would miss and the app would be offline-broken on exactly
    // the hosts it is meant to run on.
    const cached = await caches.match(request, { ignoreSearch: true, ignoreVary: true });
    if (cached) return cached;
    try {
      const response = await fetch(request);
      if (response.ok && response.type === 'basic') {
        const cache = await caches.open(CACHE);
        cache.put(request, response.clone());
      }
      return response;
    } catch (error) {
      // Offline and not precached: a navigation still gets the app shell, which
      // is the whole point of having one.
      if (request.mode === 'navigate') {
        const shell = await caches.match('./index.html', { ignoreVary: true })
          ?? await caches.match('./', { ignoreVary: true });
        if (shell) return shell;
      }
      throw error;
    }
  })());
});
